  "  color:#ffffff;",
  "  font-size:17px;",
  "  line-height:1.05;",
  "  font-weight:760;",
  "  letter-spacing:-.38px;",
  "  text-shadow:0 1px 8px rgba(5,24,56,.28);",
  "}",
  ".brand-subtitle{",
  "  margin-top:4px;",
  "  color:#c9ddf7;",
  "  font-size:10.5px;",
