  ".runtime-state.unavailable{background:#fff2f2;color:#a6545e}.runtime-state.unavailable i{background:#d86570}",
  ".alias-chip-v2{background:#eef5ff;color:#235aa7;justify-content:center;min-width:29px}.alias-chip-v2.muted{background:#f2f5f9;color:#8b9bb5}",
  ".readiness-v2 svg{width:10px;height:10px}.readiness-v2.ready{background:#eef9f4;color:#0a935a}.readiness-v2.blocked{background:#fff5e8;color:#9c6a12}",
  "",
  ".model-inspector{",
  "  border:1px solid #dfe8f4;border-radius:9px;background:linear-gradient(180deg,#fff,#fbfdff);overflow:hidden;position:relative",
  "}",
  ".inspector-head{height:64px;padding:10px 11px;border-bottom:1px solid #e8eef6;display:flex;align-items:flex-start;gap:8px}",
  ".inspector-icon{width:32px;height:32px;border-radius:8px;background:#eef5ff;color:#176fe6;display:grid;place-items:center;flex:none}.inspector-icon svg{width:18px;height:18px}",
  ".inspector-kicker{display:block;font-size:5.8px;letter-spacing:.8px;color:#8ca0bf;margin-bottom:3px}",
  ".inspector-head h3{margin:0;font-size:9.6px;color:#10214f;letter-spacing:-.12px}.inspector-head p{margin:2px 0 0;font-size:6.3px;color:#7187b0}",
  ".inspector-status{margin-left:auto;height:20px;padding:0 7px;border-radius:10px;display:flex;align-items:center;gap:5px;font-size:6.2px;font-weight:650}",
  ".inspector-status i{width:5px;height:5px;border-radius:50%}.inspector-status.callable{background:#e9faf2;color:#078b56}.inspector-status.callable i{background:#10ad69}.inspector-status.unavailable{background:#fff2f2;color:#a6545e}.inspector-status.unavailable i{background:#d86570}",
  "",
  ".inspector-section{padding:9px 11px 0}.inspector-section-title{font-size:5.8px;letter-spacing:.8px;text-transform:uppercase;color:#8195b7;font-weight:700;margin-bottom:7px}",
  ".runtime-chain{display:flex;align-items:flex-start}",
  ".runtime-chain-step{width:40px;text-align:center}.runtime-chain-step span{width:17px;height:17px;border-radius:50%;display:grid;place-items:center;margin:0 auto;background:#e9faf2;color:#0a935a;font-size:6px;font-weight:800}",
  ".runtime-chain-step small{display:block;margin-top:4px;font-size:5.3px;color:#6e83ab}.runtime-chain-line{height:1px;flex:1;background:#cbd9e8;margin-top:8px}.runtime-chain-line.active{background:linear-gradient(90deg,#2fc4a2,#5a9fed)}",
  ".runtime-chain-step.off span{background:#eef2f7;color:#8393a8}.runtime-chain-line.off{background:#e1e7ef}",
  "",
  ".fact-grid{display:grid;grid-template-columns:1fr 1fr;gap:6px}.fact-grid>div{min-height:36px;border:1px solid #e3eaf3;border-radius:7px;background:#fbfdff;padding:7px}",
  ".fact-grid span{display:block;font-size:5.6px;color:#8497b6}.fact-grid strong{display:block;margin-top:4px;font-size:7px;color:#173b78}",
