  "          <div class=\"inspector-section-title\">Policy interpretation</div>",
  "          <div id=\"policy-message\" class=\"policy-message good\">",
  "            <svg class=\"icon\"><use href=\"#i-check\"/></svg>",
  "            <div><strong>Runtime-ready</strong><span>Model and provider state allow invocation.</span></div>",
  "          </div>",
